import React, { useState, useEffect } from "react";
import axios from "axios";
import "./CreateGroupPage.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";

function CreateGroupPage() {
  const [groupNumber, setGroupNumber] = useState("");
  const [projectName, setProjectName] = useState("");
  const [selectedMembers, setSelectedMembers] = useState([]);
  const [supervisor, setSupervisor] = useState("");
  const [evaluator, setEvaluator] = useState("");
  const [allGroups, setAllGroups] = useState([]);
  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    try {
      const [studentsRes, supervisorsRes, evaluatorsRes, groupsRes, projectsRes] = await Promise.all([
        axios.get("http://localhost:5000/api/student"),
        axios.get("http://localhost:5000/api/facultyAdvisor"),
        axios.get("http://localhost:5000/api/evaluator"),
        axios.get("http://localhost:5000/api/group"),
        axios.get("http://localhost:5000/api/project"),
      ]);
      setStudents(studentsRes.data.filter((s) => !s.isGrouped));
      setSupervisors(supervisorsRes.data);
      setEvaluators(evaluatorsRes.data);
      setAllGroups(groupsRes.data);
      setProjects(projectsRes.data);
    } catch (err) {
      console.error("Error loading data:", err);
    }
  };

  const getUniqueById = (arr) => {
    const seen = new Set();
    return arr.filter((item) => {
      if (seen.has(item.userId)) return false;
      seen.add(item.userId);
      return true;
    });
  };

  const handleGroupCreation = async (e) => {
    e.preventDefault();
    if (!groupNumber.trim() || !projectName.trim() || selectedMembers.length === 0 || !supervisor || !evaluator) {
      alert("Please fill all fields, select members, supervisor, and evaluator.");
      return;
    }

    try {
      const projectRes = await axios.post("http://localhost:5000/api/project", {
        title: projectName,
        status: "Active",
      });

      const regNos = selectedMembers.map((s) => s.regNo);
      const newGroup = {
        groupNo: groupNumber,
        studentsRegno: regNos,
        projectID: projectRes.data._id,
        supervisorID: supervisor,
        evaluatorID: evaluator,
      };

      await axios.post("http://localhost:5000/api/group", newGroup);

      // Mark students as grouped
      await Promise.all(
        regNos.map((regNo) =>
          axios.patch(`http://localhost:5000/api/student/regNo/${regNo}`, { isGrouped: true })
        )
      );

      setGroupNumber("");
      setProjectName("");
      setSelectedMembers([]);
      setSupervisor("");
      setEvaluator("");

      fetchInitialData(); // Refresh everything
    } catch (err) {
      console.error("Error creating group:", err);
      alert("Failed to create group. Try again.");
    }
  };

  const handleMemberSelection = (student) => {
    if (selectedMembers.some((m) => m.userId === student.userId)) {
      setSelectedMembers(selectedMembers.filter((m) => m.userId !== student.userId));
    } else if (selectedMembers.length < 4) {
      setSelectedMembers([...selectedMembers, student]);
    } else {
      alert("You can select up to 4 members only.");
    }
  };

  const handleDisbandGroup = async (groupId, memberRegNos) => {
    try {
      await axios.delete(`http://localhost:5000/api/group/${groupId}`);
      await Promise.all(
        memberRegNos.map((regNo) =>
          axios.patch(`http://localhost:5000/api/student/regNo/${regNo}`, { isGrouped: false })
        )
      );
      fetchInitialData();
    } catch (err) {
      console.error("Error disbanding group:", err);
    }
  };

  const getSupervisorName = (id) =>
    supervisors.find((sup) => sup.userId === id)?.Name || "Unknown";

  const getEvaluatorName = (id) =>
    evaluators.find((ev) => ev.userId === id)?.name || "Unknown";

  const getProjectName = (id) =>
    projects.find((p) => p._id === id)?.title || "Unknown";

  return (
    <div className="create-group-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <div className="create-group-section">
            <div className="form-container">
              <h2>Create a New Group</h2>
              <form onSubmit={handleGroupCreation}>
                <div className="input-group">
                  <label htmlFor="group-number">Group Number</label>
                  <input
                    type="text"
                    id="group-number"
                    value={groupNumber}
                    onChange={(e) => setGroupNumber(e.target.value)}
                    required
                  />
                </div>
                <div className="input-group">
                  <label htmlFor="project-name">Project Name</label>
                  <input
                    type="text"
                    id="project-name"
                    value={projectName}
                    onChange={(e) => setProjectName(e.target.value)}
                    required
                  />
                </div>
                <button type="submit" className="submit-button">
                  Create Group
                </button>
              </form>
            </div>

            {/* Student Selection */}
            <div className="student-selection">
              <h3>All Students (not grouped)</h3>
              <table>
                <thead>
                  <tr>
                    <th>Select</th>
                    <th>Name</th>
                    <th>Reg. No</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student) => (
                    <tr key={student.userId}>
                      <td>
                        <input
                          type="checkbox"
                          checked={selectedMembers.some((m) => m.userId === student.userId)}
                          onChange={() => handleMemberSelection(student)}
                        />
                      </td>
                      <td>{student.studentName}</td>
                      <td>{student.regNo}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Supervisor and Evaluator Dropdowns */}
            <div className="supervisor-evaluator-selection">
              <h3>Select Supervisor and Evaluator</h3>
              <table>
                <thead>
                  <tr>
                    <th>Role</th>
                    <th>Name</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>Supervisor</td>
                    <td>
                      <select
                        value={supervisor}
                        onChange={(e) => setSupervisor(e.target.value)}
                        className="select-dropdown"
                        required
                      >
                        <option value="">-- Select Supervisor --</option>
                        {getUniqueById(supervisors).map((sup) => (
                          <option key={sup.userId} value={sup.userId}>
                            {sup.Name}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                  <tr>
                    <td>Evaluator</td>
                    <td>
                      <select
                        value={evaluator}
                        onChange={(e) => setEvaluator(e.target.value)}
                        className="select-dropdown"
                        required
                      >
                        <option value="">-- Select Evaluator --</option>
                        {getUniqueById(evaluators).map((ev) => (
                          <option key={ev.userId} value={ev.userId}>
                            {ev.name}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            {/* Group List */}
            <div className="groups-list">
              <h3>Created Groups</h3>
              {allGroups.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Group No</th>
                      <th>Project</th>
                      <th>Supervisor</th>
                      <th>Evaluator</th>
                      <th>Members</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allGroups.map((group) => (
                      <tr key={group._id}>
                        <td>{group.groupNo}</td>
                        <td>{getProjectName(group.projectID)}</td>
                        <td>{getSupervisorName(group.supervisorID)}</td>
                        <td>{getEvaluatorName(group.evaluatorID)}</td>
                        <td>
                          <ul>
                            {group.studentsRegno.map((regNo, idx) => (
                              <li key={idx}>{regNo}</li>
                            ))}
                          </ul>
                        </td>
                        <td>
                          <button
                            className="disband-button"
                            onClick={() => handleDisbandGroup(group._id, group.studentsRegno)}
                          >
                            Disband
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p>No groups have been created yet.</p>
              )}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage;
